INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5757580, 837968, 111673, '<td valign="top">Beautiful! Very well done!</td>', 'Beautiful! Very well done!', '2009-12-07 01:06:04.000000', NULL, 1),
(5757586, 838002, 32011, '<td valign="top">Ahh... the Western Ring Road... I know thee well..<br/> <br/>Nicely composed image.  Feels tilted b/c of the car in front, though I suspect it''s not looking at the rest of the image.</td>', 'Ahh... the Western Ring Road... I know thee well.. Nicely composed image.  Feels tilted b/c of the car in front, though I suspect it''s not looking at the rest of the image.', '2009-12-07 01:15:33.000000', NULL, 1),
(5757588, 837783, 61084, '<td valign="top">Interesting pole, but there is a lot of noise in the background as well as a glow on the right side of the pole. Not sure if it was caused during a shadow/highlight adjustment, dodge or if this is a multi exposure photo where you got some halo effect. Either way it hurts your image. Good luck.</td>', 'Interesting pole, but there is a lot of noise in the background as well as a glow on the right side of the pole. Not sure if it was caused during a shadow/highlight adjustment, dodge or if this is a multi exposure photo where you got some halo effect. Either way it hurts your image. Good luck.', '2009-12-07 01:16:52.000000', NULL, 1),
(5757592, 838013, 61084, '<td valign="top">A nice hometown scene with beautiful street lamp glow that contrasts nicely with the blue sky. Reminds me of the area where I live. Nice job.</td>', 'A nice hometown scene with beautiful street lamp glow that contrasts nicely with the blue sky. Reminds me of the area where I live. Nice job.', '2009-12-07 01:19:47.000000', NULL, 1),
(5757593, 837767, 61084, '<td valign="top">Nice crisp lines, nice silhouette on the power pole and I like the color of the background. Simple but effective. Good luck.</td>', 'Nice crisp lines, nice silhouette on the power pole and I like the color of the background. Simple but effective. Good luck.', '2009-12-07 01:20:57.000000', NULL, 1),
(5757594, 838028, 60173, '<td valign="top">He says, "I''ll crush your head... like this!"<br/> <br/>Nice all around shot.</td>', 'He says, "I''ll crush your head... like this!" Nice all around shot.', '2009-12-07 01:21:25.000000', NULL, 1),
(5757595, 837660, 34938, '<td valign="top">this in around the western ring road I am guessing...you have a nice sky here...good image overall</td>', 'this in around the western ring road I am guessing...you have a nice sky here...good image overall', '2009-12-07 01:22:09.000000', NULL, 1),
(5757597, 837726, 34938, '<td valign="top">nice HDR type shot...colours are great</td>', 'nice HDR type shot...colours are great', '2009-12-07 01:22:59.000000', NULL, 1),
(5757598, 837734, 34938, '<td valign="top">great silhouette</td>', 'great silhouette', '2009-12-07 01:23:12.000000', NULL, 1),
(5757599, 838021, 61084, '<td valign="top">Nice horizon line, and I like the simplicity of the scene. I just wish the contrast were a bit better so the power towers stood out a bit more. Overall nice job.</td>', 'Nice horizon line, and I like the simplicity of the scene. I just wish the contrast were a bit better so the power towers stood out a bit more. Overall nice job.', '2009-12-07 01:23:35.000000', NULL, 1),
(5757600, 837940, 34938, '<td valign="top">great light and silhouette</td>', 'great light and silhouette', '2009-12-07 01:23:51.000000', NULL, 1),
(5757601, 837794, 34938, '<td valign="top">brilliant...perhaps a ribbon here 9</td>', 'brilliant...perhaps a ribbon here 9', '2009-12-07 01:24:16.000000', NULL, 1),
(5757602, 837837, 34938, '<td valign="top">beautiful processing and image.., you have achieved something special here 9</td>', 'beautiful processing and image.., you have achieved something special here 9', '2009-12-07 01:24:49.000000', NULL, 1),
(5757605, 837813, 34938, '<td valign="top">LOL...creative take on the challenge and a lot of fun...</td>', 'LOL...creative take on the challenge and a lot of fun...', '2009-12-07 01:25:34.000000', NULL, 1),
(5757606, 837288, 61084, '<td valign="top">Nice capture in the fog. The red in the trees plays well off the red in the tower. It''s a pleasant and simple scene, but it seems to be missing some punch. Perhaps I would have tried to lighten the tree with a mask to give the color a bit more vibrance and adjusted the contrast just a tad. Nice job and good luck.</td>', 'Nice capture in the fog. The red in the trees plays well off the red in the tower. It''s a pleasant and simple scene, but it seems to be missing some punch. Perhaps I would have tried to lighten the tree with a mask to give the color a bit more vibrance and adjusted the contrast just a tad. Nice job and good luck.', '2009-12-07 01:26:36.000000', NULL, 1),
(5757607, 838027, 34938, '<td valign="top">great b and w conversion and brooding light...8</td>', 'great b and w conversion and brooding light...8', '2009-12-07 01:28:15.000000', NULL, 1),
(5757609, 838002, 34938, '<td valign="top">My Hometown :)</td>', 'My Hometown :)', '2009-12-07 01:29:20.000000', NULL, 1),
(5757610, 837965, 61084, '<td valign="top">A bit noisy in the background and perhaps I would have saturated the color a little bit more to give it a bit more vibrancy. I really like the duplicity of the power lines and towers that run in parallel with each other. Good luck.</td>', 'A bit noisy in the background and perhaps I would have saturated the color a little bit more to give it a bit more vibrancy. I really like the duplicity of the power lines and towers that run in parallel with each other. Good luck.', '2009-12-07 01:29:39.000000', NULL, 1),
(5757612, 837837, 109478, '<td valign="top">nice composition, 7</td>', 'nice composition, 7', '2009-12-07 01:31:32.000000', NULL, 1),
(5757613, 837780, 34938, '<td valign="top">the sky being white helps this...would look great as a large print on a wall</td>', 'the sky being white helps this...would look great as a large print on a wall', '2009-12-07 01:31:42.000000', NULL, 1),
(5757614, 837530, 61084, '<td valign="top">Nice perspective and framing, but it seems a little flat and hazy. Could have used a little contrast adjustment and a touch of USM. I do like it though. Good luck.</td>', 'Nice perspective and framing, but it seems a little flat and hazy. Could have used a little contrast adjustment and a touch of USM. I do like it though. Good luck.', '2009-12-07 01:31:56.000000', NULL, 1),
(5757615, 837731, 109478, '<td valign="top">intresting birds</td>', 'intresting birds', '2009-12-07 01:32:07.000000', NULL, 1),
(5757616, 837189, 34938, '<td valign="top">I like your edit on this...7</td>', 'I like your edit on this...7', '2009-12-07 01:32:41.000000', NULL, 1),
(5757618, 837818, 61084, '<td valign="top">Not crazy about the over-sized black border, but the shot if very nice. Good luck.</td>', 'Not crazy about the over-sized black border, but the shot if very nice. Good luck.', '2009-12-07 01:34:39.000000', NULL, 1),
(5757620, 837706, 61084, '<td valign="top">Great job. Love the colors of the foreground brush and trees, and the sky is a nice muted blue with great cloud formations. The lighting on the poles is excellent and your framed it well with a perspective that leads the viewer deep into the photo. The best I''ve seen so far. Good luck.</td>', 'Great job. Love the colors of the foreground brush and trees, and the sky is a nice muted blue with great cloud formations. The lighting on the poles is excellent and your framed it well with a perspective that leads the viewer deep into the photo. The best I''ve seen so far. Good luck.', '2009-12-07 01:38:25.000000', NULL, 1),
(5757621, 837726, 61084, '<td valign="top">Beautiful tones and hues. Love the lighting and the scene. The snow definitely helped this shot. Good luck!</td>', 'Beautiful tones and hues. Love the lighting and the scene. The snow definitely helped this shot. Good luck!', '2009-12-07 01:39:53.000000', NULL, 1),
(5757622, 838027, 61084, '<td valign="top">Excellent work. Love the contrast, the flowers in the foreground, the look on the woman''s face and the contrast between the softness and fragility of the woman against the industrial imposing power lines and towers standing over her. Good luck.</td>', 'Excellent work. Love the contrast, the flowers in the foreground, the look on the woman''s face and the contrast between the softness and fragility of the woman against the industrial imposing power lines and towers standing over her. Good luck.', '2009-12-07 01:42:22.000000', NULL, 1),
(5757624, 837813, 109478, '<td valign="top">lol, I love it. 8<br/>This is the most specail photo in this challenge, Blue Ribbon.</td>', 'lol, I love it. 8This is the most specail photo in this challenge, Blue Ribbon.', '2009-12-07 01:49:56.000000', NULL, 1),
(5757660, 837753, 106806, '<td valign="top">Meeting for a fry up? Ok I know they don''t but its funny :-) Great photo and I love the way you''ve done it black and white, and then .... oh the feet a real nice little suprise that.</td>', 'Meeting for a fry up? Ok I know they don''t but its funny :-) Great photo and I love the way you''ve done it black and white, and then .... oh the feet a real nice little suprise that.', '2009-12-07 03:27:45.000000', NULL, 1),
(5757662, 838021, 106806, '<td valign="top">I like it though is it a little too dark?</td>', 'I like it though is it a little too dark?', '2009-12-07 03:28:18.000000', NULL, 1),
(5757663, 837713, 106806, '<td valign="top">Not keen on the negative effect but thats just my artistic opinion and fact is this is a beautifully composed and nicely taken shot</td>', 'Not keen on the negative effect but thats just my artistic opinion and fact is this is a beautifully composed and nicely taken shot', '2009-12-07 03:31:48.000000', NULL, 1),
