(5764899, 837660, 88850, '<td valign="top">Really nice PP here.</td>', 'Really nice PP here.', '2009-12-12 19:55:43.000000', NULL, 1),
(5764996, 837768, 83845, '<td valign="top">A little out of focus but a really great composition.  A tripod would make the difference in sharpness.  The lines are cool!</td>', 'A little out of focus but a really great composition.  A tripod would make the difference in sharpness.  The lines are cool!', '2009-12-12 22:04:02.000000', NULL, 1),
